pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // 1. Bound to a reasonable range to avoid overflow in owner balance arithmetic
        amount = bound(amount, 1, 1000 ether);
        // Ensure the owner has no balance before we start
        vm.deal(address(this), amount);
        uint256 ownerBefore = c.owner().balance;
        uint256 contractBefore = address(c).balance;
        // Transfer ether to contract to create a balance
        vm.deal(address(this), amount);
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent, "funding failed");
        // Record owner balance after funding but before go
        uint256 ownerAfterFunding = c.owner().balance;
        // Call go via prank to simulate an external caller (irrelevant to destination)
        vm.prank(address(0x1234));
        bool ok;
        try c.go() { ok = true; } catch { ok = false; }
        // 2. If go() succeeded, owner must have received the contract's previous balance
        if (ok) {
            uint256 ownerAfter = c.owner().balance;
            // The owner should have gained exactly the contract's balance before the call
            // Since the contract balance after go() is always zero in reference,
            // ownerAfter = ownerAfterFunding + contractBefore
            assertEq(ownerAfter, ownerAfterFunding + contractBefore);
        } else {
            // If go() reverted, the owner balance should remain unchanged
            assertEq(c.owner().balance, ownerAfterFunding);
        }
    }
}

