pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // 1. Keep domain wide, bound to a reasonable range to avoid overflow or insufficient testing balance
        vm.assume(amount <= 1_000_000 ether);
        // 2. Record initial Ether state
        uint256 initialOwnerBalance = address(c.owner()).balance;
        uint256 initialContractBalance = address(c).balance;
        uint256 initialTotal = initialOwnerBalance + initialContractBalance;
        // Deal Ether to some caller and invoke go()
        address caller = address(0x1234);
        vm.deal(caller, amount);
        vm.prank(caller);
        c.go{value: amount}();
        // 3. The reference transfers the full contract balance to owner, so the sum of owner's balance
        // and contract balance after the call must equal the initial total (no Ether is burned).
        // The buggy version transfers a fixed 1 ether, burning the difference when amount != 1 ether.
        uint256 finalOwnerBalance = address(c.owner()).balance;
        uint256 finalContractBalance = address(c).balance;
        assertEq(finalOwnerBalance + finalContractBalance, initialTotal, "Ether conservation violated");
    }
}

