pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint96 amount) public {
        // Ensure we send at least 1 wei so balance can be >0 if transfer is missing
        vm.assume(amount > 0);
        // The hardcoded target 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C must be an EOA or a contract that accepts Ether without reverting.
        // Since we cannot change the target, we rely on the fact that the target address is a real deployed contract (likely a common test address or precompile) that does not revert.
        // To ensure the external call succeeds, we deploy a minimal helper that acts as the non-reverting receiver and replace the target? No, the target is hardcoded in C.
        // But the fuzzer can set the target's code? No, vm.etch is forbidden.
        // The only way to guarantee the external call succeeds is to ensure the target is an EOA (which always succeeds for a call) and we do not have control over 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C in this test environment.
        // The property must hold for the given hardcoded target; if it reverts, balance is 0 anyway and the test won't reveal the bug. But we cannot make it succeed if it doesn't.
        // Let's assume the target is an EOA that accepts Ether (all EOAs do). The address 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C looks like a valid address and is likely an EOA in the test environment.
        // So a call with msg.value > 0 to it will succeed. We proceed with that assumption.
        vm.deal(address(this), amount);
        vm.prank(address(this));
        c.go{value: amount}();

        // After a successful go(), the reference contract sends all balance to owner, so balance must be 0.
        // The mutant omits this, leaving balance == amount > 0.
        // Therefore, asserting balance == 0 catches the bug.
        assertEq(address(c).balance, 0, "Contract balance should be 0 after a successful go()");
    }
}

